mod codec;use codec::*;use serde_json::{json,Value};use std::collections::BTreeMap;use zopro_bn254::{Field,Fr,G1Affine,G2Affine};
pub fn canonical(p:Point)->(Point,usize,bool){let mut best=p;let mut key=p.key();let(mut power,mut neg)=(0,false);let mut q=p;for e in 0..3{for n in[false,true]{let r=if n{q.neg()}else{q};if r.key()<key{best=r;key=r.key();power=e;neg=n;}}q=q.phi();}assert_eq!(q,p);(best,power,neg)}
pub fn counts(points:&[Point])->Value{let(mut exact,mut signed,mut orbits)=(BTreeMap::<[u8;129],usize>::new(),BTreeMap::new(),BTreeMap::new());let mut zero=0;for&p in points{if p.zero(){zero+=1;continue;}*exact.entry(p.key()).or_default()+=1;*signed.entry(p.key().min(p.neg().key())).or_insert(0usize)+=1;*orbits.entry(canonical(p).0.key()).or_insert(0usize)+=1;}let n=points.len()-zero;json!({"input_points":points.len(),"identities":zero,"nonidentity_points":n,"exact_classes":exact.len(),"exact_excess":n-exact.len(),"signed_classes":signed.len(),"signed_excess":n-signed.len(),"six_orbit_classes":orbits.len(),"six_orbit_excess":n-orbits.len(),"additional_phi_alias_excess":signed.len()-orbits.len(),"max_orbit_multiplicity":orbits.values().max().copied().unwrap_or(0),"ordered_points_sha256":points_digest(points)})}
pub fn group(points:&[Point],s:&[Fr])->(Vec<Point>,Vec<Fr>){assert_eq!(points.len(),s.len());let mut map=BTreeMap::new();let mut accum=vec![];let mut values=vec![];for(&p,&v)in points.iter().zip(s){if v==Fr::ZERO{continue;}let index=*map.entry(v.to_canonical()).or_insert_with(||{values.push(v);accum.push(p.mul(Fr::ZERO).sum());values.len()-1});accum[index].add_point(p);}let p=accum.into_iter().map(|p|p.affine()).collect();(p,values)}
fn main(){let mut rows=BTreeMap::new();let inputs=read(root("inputs.json"));let fixtures=inputs["fixtures"].as_object().unwrap();for(shape,case)in image_cases(){let p=image_points(std::path::Path::new(case["image"].as_str().unwrap()),case["image_sha256"].as_str().unwrap());for(query,points)in&p{rows.insert(format!("{shape}/key/{query}"),counts(points));}for query in["A","B"]{let v=&fixtures[&format!("{shape}-{query}")];let(fp,s)=fixture(v);assert_eq!(fp,p[query],"key/fixture point binding {shape}/{query}");let(g,gs)=group(&fp,&s);let mut row=counts(&g);row["policy"]=policy(&s);row["full_scalar_grouping_requested_even_when_data_gate_declines"]=json!(true);row["retained_scalar_values_sha256"]=json!(hash(&gs.iter().flat_map(|s|s.to_be_bytes()).collect::<Vec<_>>()));rows.insert(format!("{shape}/full_exact_scalar_groups/{query}"),row);}}
 let additional=rows.values().map(|v|v["additional_phi_alias_excess"].as_u64().unwrap()).sum::<u64>();save(root("analysis.json"),&json!({"complete":true,"rows":rows,"additional_phi_alias_excess_sum_across_views":additional,"views_overlap_not_unique_point_total":true,"additional_aliases_need_work_bound_review":additional!=0,"native_optimization_implemented":false,"production_changed":false,"new_proofs":0,"canonical_proof_ledger":30846,"goal_achieved":false,"not_latency_or_memory_qualification":true}));println!("{}",serde_json::to_string_pretty(&read(root("analysis.json"))).unwrap());}
#[cfg(test)]mod tests{use super::*;
 #[test]fn cube_roots_and_both_curve_eigenvalues(){assert_ne!(BETA,zopro_bn254::Fq::ONE);assert_eq!(BETA.square()*BETA,zopro_bn254::Fq::ONE);assert_eq!(LAMBDA.square()*LAMBDA,Fr::ONE);for g in[Point::G1(G1Affine::GENERATOR),Point::G2(G2Affine::GENERATOR)]{let l=g.eigenvalue();assert_eq!(g.phi(),g.mul(l));assert_eq!(g.phi().phi().phi(),g);for i in[1u64,2,3,17,101,65537,u64::MAX]{let p=g.mul(Fr::from(i));let key=canonical(p).0.key();for mut q in[p,p.neg()]{for _ in 0..3{let(c,e,n)=canonical(q);assert_eq!(c.key(),key);let f=[Fr::ONE,l.square(),l][e];assert_eq!(c.mul(if n{-f}else{f}),q);q=q.phi();}}}}}
 #[test]fn orbit_counts_identity_and_known_collisions(){for g in[Point::G1(G1Affine::GENERATOR),Point::G2(G2Affine::GENERATOR)]{let p=vec![g,g,g.neg(),g.phi(),g.phi().neg(),g.phi().phi(),g.phi().phi().neg(),g.mul(Fr::ZERO)];let c=counts(&p);assert_eq!(c["identities"],1);assert_eq!(c["exact_excess"],1);assert_eq!(c["signed_excess"],4);assert_eq!(c["six_orbit_excess"],6);assert_eq!(c["additional_phi_alias_excess"],2);}}
 #[test]fn exact_scalar_groups_and_orbit_coefficients_preserve_sum(){for g in[Point::G1(G1Affine::GENERATOR),Point::G2(G2Affine::GENERATOR)]{let l=g.eigenvalue();let mut points=vec![];let mut values=vec![];for i in 0..35{let p=g.mul(Fr::from((i%5+1)as u64));points.push(if i%2==0{p.phi()}else{p.neg()});values.push(match i%7{0=>Fr::ZERO,1=>-Fr::ONE,_=>Fr::from((i%3+1)as u64)});}let mut expected=g.mul(Fr::ZERO).sum();for(&p,&s)in points.iter().zip(&values){expected.add_point(p.mul(s));}let(p,s)=group(&points,&values);let mut grouped=g.mul(Fr::ZERO).sum();let mut orbit=BTreeMap::<[u8;129],(Point,Fr)>::new();for(p,s)in p.into_iter().zip(s){grouped.add_point(p.mul(s));let(c,e,n)=canonical(p);let f=[Fr::ONE,l.square(),l][e];orbit.entry(c.key()).or_insert((c,Fr::ZERO)).1+=s*if n{-f}else{f};}assert_eq!(expected.affine(),grouped.affine());let mut result=g.mul(Fr::ZERO).sum();for(_, (p,s))in orbit{result.add_point(p.mul(s));}assert_eq!(expected.affine(),result.affine());}}
}
